/**
 * Confluence Node - Version 1
 * Discriminator: resource=page, operation=create
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Create a new page in a space */
export type ConfluenceV1PageCreateParams = {
  resource: 'page';
  operation: 'create';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * The space to create the page in
 * @searchListMethod searchSpaces
 * @default {"mode":"list","value":""}
 */
    space?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * The title of the new page
 */
    title: string | Expression<string>;
/**
 * How the page content below is interpreted
 * @default plainText
 */
    bodyFormat?: 'atlas_doc_format' | 'plainText' | 'storage' | Expression<string>;
/**
 * Page content as plain text; each line becomes a paragraph. Blank lines and leading whitespace are removed.
 * @displayOptions.show { bodyFormat: ["plainText"] }
 */
    bodyPlainText?: string | Expression<string>;
/**
 * Page content in Confluence storage format
 * @displayOptions.show { bodyFormat: ["storage"] }
 */
    bodyStorage?: string | Expression<string>;
/**
 * Page content as an Atlassian Document Format document
 * @displayOptions.show { bodyFormat: ["atlas_doc_format"] }
 */
    bodyAdf?: IDataObject | string | Expression<string>;
/**
 * The page to create the new page under. Leave empty to create under the space homepage.
 * @searchListMethod getPages
 * @displayOptions.hide { /options.rootLevel: [true] }
 * @default {"mode":"list","value":""}
 */
    parentPage?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to create the page as a draft instead of publishing it
     * @default false
     */
    createAsDraft?: boolean | Expression<boolean>;
    /** Whether only the creating user can view and edit the page. The creator is the connected account, which needs permission to restrict content in the space.
     * @default false
     */
    private?: boolean | Expression<boolean>;
    /** Whether to create the page at the space root, outside the space homepage tree. Cannot be combined with a parent page.
     * @default false
     */
    rootLevel?: boolean | Expression<boolean>;
  };
};

export type ConfluenceV1PageCreateNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1PageCreateParams> & { credentials?: Credentials };
};